"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps, ReactNode } from "react";

export type KeyframesPrimitiveProps = Omit<ComponentProps<typeof motion.div>, "children"> & { children: ReactNode };

export function KeyframesPrimitive({ children, ...props }: KeyframesPrimitiveProps) {
  const reduceMotion = useReducedMotion();
  return (
    <motion.div
      {...props}
      initial={reduceMotion ? false : { opacity: 0.35, x: 0 }}
      animate={reduceMotion ? { opacity: 1, x: 0 } : { opacity: [0.35, 1, 0.72, 1], x: [0, 18, -8, 0] }}
      transition={{ duration: reduceMotion ? 0.12 : 0.72, ease: [0.23, 1, 0.32, 1] }}
      data-fill="both"
      data-steps={4}
    >
      {children}
    </motion.div>
  );
}
